import Foundation

/// The committed fixtures of a genuine release, generated by `Scripts/make-update-fixtures.sh` with the project's own
/// identities. Tests that need them are skipped while they are absent.
enum UpdateFixtures {
    static let folder = URL(fileURLWithPath: #filePath).deletingLastPathComponent().appending(path: "UpdateFixtures")

    /// The notarised, stapled app signed with the project's Developer ID.
    static let developerIDApp = folder.appending(path: "DeveloperID/TrackpadLauncher.app")
    /// The same app signed with the Apple Development identity, as Debug and perf builds are.
    static let appleDevelopmentApp = folder.appending(path: "AppleDevelopment/TrackpadLauncher.app")
    /// The release archive, as the release process builds it.
    static let archive = folder.appending(path: "TrackpadLauncher-fixture.aar")
    /// Version, minimum macOS, team, identifier and the file manifest of the Developer ID app.
    static let record = folder.appending(path: "fixture.json")

    static var arePresent: Bool {
        [developerIDApp, appleDevelopmentApp, archive, record].allSatisfy {
            FileManager.default.fileExists(atPath: $0.path)
        }
    }

    struct Record: Decodable {
        let version: String
        let minimumMacOS: String
        let team: String
        let identifier: String
        let manifest: [String: String]
    }

    static func loadRecord() throws -> Record {
        try JSONDecoder().decode(Record.self, from: Data(contentsOf: record))
    }
}
